@Service @RequiredArgsConstructor
class OrderService {
    private final AuditService audit;
    @Transactional
    public void place(Order o) {
        orderMapper.insert(o);
        audit.log("PLACE", o.getId());   // REQUIRES_NEW：主事务失败日志仍在
        if (o.bad()) throw new RuntimeException("fail");
    }
}
@Service
class AuditService {
    @Transactional(propagation = Propagation.REQUIRES_NEW)
    public void log(String action, long id) {
        auditMapper.insert(action, id);
    }
}

